import random

gesucht = random.randint(1, 100)
print(f'(Zur Kontrolle: gesucht ist {gesucht}.)')

tipp = int(input('Welche Zahl suche ich? '))

if tipp < gesucht:
    print('Zu niedrig.')
elif tipp > gesucht:
    print('Zu hoch.')
else:
    print('Richtig!')

import random

gesucht = random.randint(1, 100)
tipp = 0
versuche = 0

while tipp != gesucht and versuche < 7:
    tipp = int(input('Welche Zahl suche ich? '))
    versuche += 1

    if tipp < gesucht:
        print('Zu niedrig.')
    elif tipp > gesucht:
        print('Zu hoch.')

if tipp == gesucht:
    print(f'Richtig! Du hast {versuche} von 7 Versuchen gebraucht.')
else:
    print(f'Aufgebraucht. Gesucht war {gesucht}.')

aufgaben_vertiefung.loesung:
import random

gesucht = random.randint(1, 100)
tipp = 0
versuche = 0
tipps = []

while tipp != gesucht and versuche < 7:
    eingabe = input('Welche Zahl suche ich? ')

    try:
        tipp = int(eingabe)
    except ValueError:
        print('Das ist keine Zahl. Versuch es nochmal.')
        continue

    versuche += 1
    tipps.append(tipp)

    if tipp < gesucht:
        print('Zu niedrig.')
    elif tipp > gesucht:
        print('Zu hoch.')

if tipp == gesucht:
    print(f'Richtig! Du hast {versuche} von 7 Versuchen gebraucht.')
else:
    print(f'Aufgebraucht. Gesucht war {gesucht}.')

print(f'Deine Tipps: {tipps}')
